//! Golden images of the client's M0 test scene, rendered headless.
//!
//! - `test_scene.png`: the scene as shown without game data (procedural checkerboard).
//! - `test_scene_surface.png`: the scene after a decoded surface replaced the checkerboard;
//!   the "surface" here is a synthetic, non-square RGBA image with transparent texels,
//!   standing in for a texture from the user's archives (no game data is involved).
//!
//! Both PNGs are generated by this test (`TESSERA_BLESS=1 cargo test -p tessera-client
//! --test scene_golden`). Comparison rules: `crates/render/tests/support/golden.rs`.

#[path = "../../../crates/render/tests/support/golden.rs"]
mod golden;
#[path = "../../../crates/render/tests/support/gpu.rs"]
mod gpu;

use std::path::{Path, PathBuf};

use tessera_client::data::DecodedTexture;
use tessera_client::net::EntityView;
use tessera_client::scene::{CLEAR_COLOR, Scene};
use tessera_render::{OffscreenFormat, RenderError, Renderer, RgbaImage};

const WIDTH: u32 = 480;
const HEIGHT: u32 = 270;

fn golden_path(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/golden")
        .join(name)
}

fn render(r: &mut Renderer<'static>, scene: &Scene) -> Result<RgbaImage, RenderError> {
    let target = r.create_offscreen_target(WIDTH, HEIGHT, OffscreenFormat::Rgba8Srgb)?;
    let mut frame = r.begin_offscreen_frame(&target)?;
    scene.draw(&mut frame, std::iter::empty::<(bool, &EntityView)>());
    r.end_frame(frame)?;
    r.read_pixels(&target)
}

/// 96x64 synthetic surface: diagonal colour bands with a transparent circular hole.
fn synthetic_surface() -> DecodedTexture {
    let (w, h) = (96u32, 64u32);
    let mut rgba = Vec::with_capacity((w * h * 4) as usize);
    for y in 0..h {
        for x in 0..w {
            let band = ((x + y) / 12) % 3;
            let mut px = match band {
                0 => [0x3c, 0xb4, 0x8c, 0xff],
                1 => [0xe6, 0xe6, 0xd2, 0xff],
                _ => [0x8c, 0x28, 0x50, 0xff],
            };
            let (dx, dy) = (x as i32 - 64, y as i32 - 32);
            if dx * dx + dy * dy < 14 * 14 {
                px[3] = 0;
            }
            rgba.extend_from_slice(&px);
        }
    }
    DecodedTexture {
        did: 0x4100_0000,
        format: "synthetic",
        width: w,
        height: h,
        rgba,
    }
}

#[test]
fn test_scene_matches_golden() -> Result<(), RenderError> {
    let Some(mut r) = gpu::headless_renderer(CLEAR_COLOR) else {
        return Ok(());
    };
    let mut scene = Scene::new(&mut r)?;
    let img = render(&mut r, &scene)?;
    assert_eq!(render(&mut r, &scene)?, img, "render is not deterministic");
    golden::check(
        &golden_path("test_scene.png"),
        &img,
        golden::Tolerance::default(),
    );

    scene.set_surface(&mut r, &synthetic_surface())?;
    assert_eq!(scene.shown().did, Some(0x4100_0000));
    let img = render(&mut r, &scene)?;
    golden::check(
        &golden_path("test_scene_surface.png"),
        &img,
        golden::Tolerance::default(),
    );
    Ok(())
}
